(()=>{'use strict';const $=s=>document.querySelector(s),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=value=>Number(value||0).toLocaleString('fa-IR')+' تومان',fa=value=>Number(value).toLocaleString('fa-IR');let items=[],cart=[],groups=[],preview=location.pathname.includes('storefront-preview'),key=crypto.randomUUID(),busy=false,lastFocus;let toastTimer;const C=window.PBFrameCatalog,selected=new Map();const sharedStyles=document.createElement('style');sharedStyles.textContent=C.cardStyles();document.head.insertBefore(sharedStyles,document.querySelector('link[rel=stylesheet]'));const newToken=()=>btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(32)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');let checkoutToken=newToken();try{const pending=JSON.parse(localStorage.getItem('storefront-pending'));if(pending?.key&&pending?.token){key=pending.key;checkoutToken=pending.token;}}catch{}
const request=async(url,options={})=>{const r=await fetch(url,{...options,headers:{'content-type':'application/json',...options.headers}}),data=await r.json();if(!r.ok)throw data;return data;};
const errors={bank_details_unavailable:'فروشگاه هنوز حساب بانکی را ثبت نکرده است.',store_cart_changed:'موجودی یا وضعیت کالا تغییر کرده؛ سبد را بررسی کنید.',invalid_customer_details:'نام کامل و شماره موبایل معتبر وارد کنید.',delivery_address_required:'آدرس تحویل را کامل وارد کنید.',try_again_later:'لطفاً کمی بعد دوباره تلاش کنید.',order_already_submitted:'این سفارش قبلاً ثبت شده است. بخش پیگیری سفارش را بررسی کنید.',receipt_not_replaceable:'رسید قبلاً ارسال شده است.',store_domain_pending:'اتصال دامنه هنوز تکمیل نشده است.'};const errorText=e=>errors[e?.error]||'انجام نشد؛ لطفاً دوباره تلاش کنید.';
const label=item=>{const s=item.variant_specs||{};return [s.color,s.diameterCm?'قطر '+s.diameterCm:s.widthCm&&s.heightCm?s.widthCm+'×'+s.heightCm:'',s.thicknessMm?'ضخامت '+s.thicknessMm:''].filter(Boolean).join(' · ');};
function modelCard(g){const item=C.choose(g,selected.get(g.id));selected.set(g.id,item.id);const template=document.createElement('template');template.innerHTML=C.card(g,item.id,{esc,money}).trim();const card=template.content.firstElementChild;card.classList.add('product');card.dataset.group=g.id;card.querySelector('.saleItemBuy').classList.add('buy');const add=card.querySelector('[data-add-sale-cart]');add.dataset.add=item.id;add.disabled=preview;card.querySelector('.saleItemPrice').innerHTML=price(item);if(!g.material&&!item.variant_specs?.material)card.querySelector('.saleItemInfo small')?.remove();return card;}
function draw(){const term=$('#search').value.trim().toLocaleLowerCase('fa'),sort=$('#sort').value;let visible=groups.filter(g=>[g.model,g.material,g.description,...g.variants.map(C.label)].join(' ').toLocaleLowerCase('fa').includes(term));if(sort!=='default'){const lowest=g=>Math.min(...g.variants.map(x=>Number(x.sale_price)));visible.sort((a,b)=>(lowest(a)-lowest(b))*(sort==='low'?1:-1));}$('#products').replaceChildren(...visible.map(modelCard));if(!visible.length)$('#products').innerHTML='<p class="empty">'+(groups.length?'کالایی با این جست‌وجو پیدا نشد.':'هنوز کالایی در سایت این فروشگاه منتشر نشده است.')+'</p>';$('#productCount').textContent=fa(visible.length)+' مدل';}
function changeChoice(control){const card=control.closest('.product'),group=groups.find(x=>String(x.id)===card.dataset.group),current=items.find(x=>String(x.id)===card.dataset.selectedItem),next=C.changeChoice(group,current,control.dataset.frameChoice,control.dataset.frameColor??control.value);if(!next)return;const quantity=card.querySelector('input[type=number]').value;selected.set(group.id,next.id);const fresh=modelCard(group);fresh.querySelector('input[type=number]').value=quantity;card.replaceWith(fresh);const key=control.dataset.frameChoice,color=control.dataset.frameColor;const focus=color!==undefined?fresh.querySelector('[data-frame-color="'+CSS.escape(color)+'"]'):fresh.querySelector('[data-frame-choice="'+key+'"]');focus?.focus({preventScroll:true});}
function showProductDialog(title,content){$('#productDialogTitle').textContent=title;$('#productDialogBody').replaceChildren(content);$('#productDialog').showModal();document.body.style.overflow='hidden';}
$('#closeProductDialog').onclick=()=>$('#productDialog').close();$('#productDialog').addEventListener('close',()=>{document.body.style.overflow='';});$('#productDialog').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const box=e.currentTarget.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)e.currentTarget.close();});
function price(item){return (Number(item.channel_discount_percent)>0?'<del aria-label="قیمت قبل از تخفیف">'+money(item.channel_gross_price)+'</del><span class="frameDiscountBadge">'+fa(item.channel_discount_percent)+'٪ تخفیف</span>':'')+money(item.sale_price);}
function cartDraw(){const count=cart.reduce((sum,row)=>sum+row.quantity,0);$('#cartCount').textContent=fa(count);$('#cartLines').innerHTML=cart.map(row=>{const item=items.find(x=>x.id===row.itemId);return '<div class="cartline"><div><b>'+esc(item.title)+'</b><br><small>'+esc(label(item))+' · '+fa(row.quantity)+' عدد</small><div>'+money(item.sale_price*row.quantity)+'</div></div><button data-remove="'+esc(item.id)+'">حذف</button></div>';}).join('')||'<p class="empty">سبد خرید خالی است.</p>';$('#cartTotal').textContent=money(cart.reduce((sum,row)=>sum+Number(items.find(x=>x.id===row.itemId).sale_price)*row.quantity,0));$('#checkout').hidden=!cart.length||preview;}
function closeCart(){$('#cartOverlay').hidden=true;document.body.style.overflow='';lastFocus?.focus();}$('#cartButton').onclick=()=>{lastFocus=document.activeElement;cartDraw();$('#cartOverlay').hidden=false;document.body.style.overflow='hidden';$('#closeCart').focus();};$('#closeCart').onclick=closeCart;$('#cartOverlay').onclick=e=>{if(e.target===$('#cartOverlay'))closeCart();};document.addEventListener('keydown',e=>{if($('#cartOverlay').hidden)return;if(e.key==='Escape')closeCart();if(e.key==='Tab'){const all=[...$('#cartOverlay').querySelectorAll('button,input,textarea,select')].filter(x=>!x.disabled&&x.getClientRects().length),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});document.querySelectorAll('.storeLinks a').forEach(link=>link.addEventListener('click',()=>{document.querySelectorAll('.storeLinks a').forEach(item=>item.classList.toggle('active',item===link));}));$('#search').oninput=draw;$('#sort').onchange=draw;
$('#products').onchange=e=>{if(e.target.matches('select[data-frame-choice]'))changeChoice(e.target);};
$('#products').addEventListener('click',e=>{const color=e.target.closest('[data-frame-color]');if(color){changeChoice(color);return;}const qty=e.target.closest('[data-sale-qty-delta]');if(qty){const input=qty.closest('.qtyStepperV810').querySelector('input');input.value=Math.max(1,Math.min(99,(Number(input.value)||1)+Number(qty.dataset.saleQtyDelta)));return;}const description=e.target.closest('[data-frame-description]');if(description){const group=groups.find(x=>String(x.id)===description.closest('.product').dataset.group),text=document.createElement('p');text.textContent=group.description;showProductDialog(group.model,text);return;}const photo=e.target.closest('[data-frame-show-gallery]');if(photo){const item=items.find(x=>String(x.id)===photo.dataset.frameShowGallery),urls=item.thumbnail_urls?.length?item.thumbnail_urls:item.image_urls?.length?item.image_urls:item.color_image_urls?.length?item.color_image_urls:[item.thumbnail_url||item.image_url],src=[...new Set(urls.filter(Boolean))][Number(photo.dataset.frameGalleryIndex)||0];if(!src)return;const img=document.createElement('img');img.src=src;img.alt=item.variant_specs?.baseModel||item.model||item.title;showProductDialog(img.alt,img);}});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add&&!preview){const quantity=Number(add.closest('.product').querySelector('input').value);if(!Number.isInteger(quantity)||quantity<1||quantity>99)return;const item=items.find(x=>x.id===add.dataset.add),row=cart.find(x=>x.itemId===item.id);if(row)row.quantity=Math.min(99,row.quantity+quantity);else cart.push({itemId:item.id,quantity});key=crypto.randomUUID();cartDraw();$('#toast').textContent='به سبد خرید اضافه شد';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',1800);}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(x=>x.itemId!==remove.dataset.remove);key=crypto.randomUUID();cartDraw();}});
$('#checkout [name=deliveryMethod]').onchange=e=>{const courier=e.target.value==='courier';$('#addressField').hidden=!courier;$('#checkout [name=address]').required=courier;};
function saveOrder(value){localStorage.setItem('storefront-order',JSON.stringify(value));location.hash='order='+value.id+'.'+value.accessToken;}
async function tracking(saved){const response=await request('/api/storefront/orders/'+saved.id,{headers:{authorization:'Bearer '+saved.accessToken}}),o=response.order;$('#tracking').innerHTML='<section class="intro"><h2>پیگیری سفارش '+esc(o.id.slice(0,8).toUpperCase())+'</h2><p>'+esc(({awaiting_receipt:'در انتظار ارسال رسید',pending_review:'رسید در انتظار تأیید فروشگاه',in_production:'در حال آماده‌سازی',confirmed:'تأیید شده',ready:'آماده تحویل',delivered:'تحویل داده شده',cancelled:'لغو شده'})[o.status])+'</p><div class="total"><span>مبلغ سفارش</span><b>'+money(o.totalAmount)+'</b></div>'+(o.reviewNote?'<p>'+esc(o.reviewNote)+'</p>':'')+(o.status==='awaiting_receipt'?'<div class="bank"><span>اطلاعات واریز به فروشگاه</span><b>'+esc(o.bankDetails.accountHolder)+'</b><b dir="ltr">'+esc(o.bankDetails.cardNumber)+'</b><span dir="ltr">'+esc(o.bankDetails.iban)+'</span></div><form id="receipt" class="checkout"><label>تصویر رسید واریز<input type="file" accept="image/jpeg,image/png,image/webp" required></label><button>ارسال رسید پرداخت</button><p class="message" role="status"></p></form>':'')+'<p><a id="trackingLink">لینک پیگیری این سفارش را نگه دارید</a></p><button id="refreshOrder">به‌روزرسانی وضعیت</button></section>';$('#trackingLink').href=location.origin+'/#order='+saved.id+'.'+saved.accessToken;$('#refreshOrder').onclick=()=>tracking(saved).catch(e=>$('#error').textContent=errorText(e));const form=$('#receipt');if(form)form.onsubmit=async e=>{e.preventDefault();const file=form.querySelector('input').files?.[0],button=form.querySelector('button'),msg=form.querySelector('[role=status]');if(!file||file.size>6*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){msg.textContent='عکس JPG، PNG یا WebP با حجم حداکثر ۶ مگابایت انتخاب کنید.';return;}button.disabled=true;try{const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});await request('/api/storefront/orders/'+saved.id+'/receipt',{method:'POST',headers:{authorization:'Bearer '+saved.accessToken},body:JSON.stringify({image})});await tracking(saved);}catch(error){msg.textContent=errorText(error);button.disabled=false;}};}
$('#checkout').onsubmit=async e=>{e.preventDefault();if(preview||busy||!cart.length)return;busy=true;const button=e.currentTarget.querySelector('button'),message=$('#checkoutError');button.disabled=true;message.textContent='';try{const body=Object.fromEntries(new FormData(e.currentTarget));body.items=cart;body.idempotencyKey=key;body.accessToken=checkoutToken;localStorage.setItem('storefront-pending',JSON.stringify({key,token:checkoutToken}));const out=await request('/api/storefront/orders',{method:'POST',body:JSON.stringify(body)});saveOrder(out);localStorage.removeItem('storefront-pending');key=crypto.randomUUID();checkoutToken=newToken();cart=[];cartDraw();closeCart();await tracking(out);$('#tracking').scrollIntoView({behavior:'smooth'});}catch(error){message.textContent=errorText(error);}finally{busy=false;button.disabled=false;}};
function sampleProducts(){const rows=[];for(const [index,model,material,base]of [[0,'قاب مدرن','چوب',350000],[1,'قاب مینیمال','PVC',240000],[2,'شاسی ساده','MDF',190000]])for(const [color,hex]of [['مشکی','#292724'],['سفید','#eeeae2']])for(const [w,h,multiplier]of [[20,30,1],[30,40,1.5]]){const svg='<svg xmlns="http://www.w3.org/2000/svg" width="500" height="360"><rect width="500" height="360" fill="#f8f6f2"/><rect x="145" y="20" width="210" height="320" rx="2" fill="'+hex+'"/><rect x="155" y="30" width="190" height="300" fill="#fff"/><rect x="174" y="49" width="152" height="262" fill="#e5dfd3"/><path d="M174 240l60-100 40 65 52-80v186H174z" fill="#a4b0a0"/><circle cx="280" cy="95" r="20" fill="#c9b391"/></svg>',gross=Math.round(base*multiplier),discount=index===0?15:0;rows.push({id:'sample-'+index+'-'+color+'-'+w,title:model,model,description:'نمونه نمایشی برای بررسی ظاهر کارت، انتخاب رنگ و سایز و نمایش تخفیف؛ این محصول برای خرید منتشر نشده است.',sale_price:Math.round(gross*(100-discount)/100),channel_gross_price:gross,channel_discount_percent:discount,image_url:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg),variant_specs:{baseId:'sample-model-'+index,baseModel:model,material,color,modelColors:['مشکی','سفید'],widthCm:w,heightCm:h,thicknessMm:20,sizeOnly:true}});}return rows;}
(async()=>{try{const out=await request(preview?'/api/rental/storefront/preview':'/api/storefront/catalog');const sample=preview&&new URLSearchParams(location.search).get('sample')==='1';items=sample?sampleProducts():out.items;if(sample)$('#previewNotice').textContent='محصولات و قیمت‌های نمونه — فقط برای بررسی ظاهر؛ ثبت سفارش غیرفعال است.';document.title=out.shop.name;$('#storeName').textContent=out.shop.name;$('#title').textContent=out.shop.name;$('#about').textContent=out.shop.description||(out.shop.production?'قاب و شاسی در رنگ‌ها و اندازه‌های متنوع؛ انتخاب مدل، مشاهده قیمت و خرید مستقیم از فروشگاه.':'محصولات و تجهیزات عکاسی و فیلم‌برداری؛ بررسی مشخصات و خرید مستقیم از فروشگاه.');$('#footer').textContent='خرید مستقیم از '+out.shop.name;$('#footerStoreName').textContent=out.shop.name;$('#storeType').textContent=out.shop.production?'فروشگاه قاب و شاسی':'فروشگاه تجهیزات عکاسی و فیلم‌برداری';$('#aboutTitle').textContent='درباره '+out.shop.name;$('#storeDescription').textContent=[out.shop.description,(out.shop.production?'برای عکس‌های خانوادگی، پرتره و آثار هنری، قاب و شاسی متناسب با فضای خود انتخاب کنید. رنگ و سایز هر مدل را روی کارت محصول بررسی کنید و قیمت نهایی را پیش از ثبت سفارش ببینید.':'تجهیزات موردنیاز عکاسی و فیلم‌برداری خود را در این فروشگاه بررسی و انتخاب کنید.')+'\nسفارش مستقیماً برای همین فروشگاه ارسال می‌شود. پس از ثبت، اطلاعات واریز نمایش داده می‌شود و می‌توانید رسید پرداخت را ارسال و وضعیت سفارش را با لینک اختصاصی دنبال کنید.'].filter(Boolean).join('\n\n');if(out.shop.rentalEnabled&&!out.shop.production){window.PBStorefrontRental?.init(out.shop,preview);$('#about').textContent=out.shop.description||'اجاره تجهیزات ویژه عکاسان از طریق آفیش، همراه با امکان خرید عمومی کالاهای فروشگاه.';$('#storeDescription').textContent=[out.shop.description,'آفیش تجهیزات فقط برای عکاسان دارای حساب و همکاری تأییدشده با فروشگاه است. خرید عمومی نیازی به ورود عکاس ندارد و از قیمت اختصاصی سایت استفاده می‌کند.'].filter(Boolean).join('\n\n');}if(out.shop.saleEnabled===false){$('#catalog').hidden=true;$('#cartButton').hidden=true;$('#salesNav').hidden=true;$('#salesTopLink').hidden=true;document.querySelector('.shoppingSteps').hidden=true;}const contact=$('#contactDetails');if(out.shop.phone){const phone=document.createElement('a');phone.textContent='تماس با فروشگاه: '+out.shop.phone;const digits=String(out.shop.phone).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[^0-9+]/g,'');if(digits)phone.href='tel:'+digits;contact.append(phone);}if(out.shop.address){const address=document.createElement('p');address.textContent='نشانی: '+out.shop.address;contact.append(address);}$('#previewNotice').hidden=!preview;groups=C.groups(items).filter(g=>g.variants.length);draw();cartDraw();if(!preview){let saved;const match=location.hash.match(/^#order=([0-9a-f-]{36})\.([A-Za-z0-9_-]{43})$/i);try{saved=match?{id:match[1],accessToken:match[2]}:JSON.parse(localStorage.getItem('storefront-order'));}catch{}if(saved?.id&&saved?.accessToken)await tracking(saved).catch(error=>{$('#error').textContent=errorText(error);});}}catch(error){$('#title').textContent='فروشگاه';$('#error').textContent=errorText(error);}})();
})();
